const d = $('Decide').first().json;
const r = $('Atualiza no Asaas').first().json || {};
const erro = r.error ? motivo(r) : '';
// Avisos ligados nesta edição (cliente ganhou e-mail): conta na mensagem; se falhou, pede para ligar à mão.
const p = $('Pede notificacoes da edicao').first().json || {};
const falhas = p.ligou ? $input.all().map((i) => i.json || {}).filter((j) => j.error).length : 0;
const semAvisos = p.erroLigar || falhas ? 'Não consegui ligar o aviso por e-mail no Asaas do ' + d.de + '; ligue à mão.' : '';
return [{ json: { ok: !erro, acao: 'atualizar', id: d.idAtual, conta: d.de,
  info: p.ligou && !semAvisos ? 'Aviso por e-mail ligado no Asaas (o cliente passou a ter e-mail).' : '',
  aviso: erro ? 'O Asaas do ' + d.de + ' não aceitou a atualização (' + erro + ').' : semAvisos } }];

