const d = $('Decide').first().json;
const p = $('Pede criacao').first().json;
const r = $input.first().json || {};
const novoId = p.pular ? '' : String(r.id || '');
const erro = p.pular ? p.motivoBusca : (novoId ? '' : motivo(r));
return [{ json: { conta: d.destino, metodo: 'GET', url: A + '/customers/' + encodeURIComponent(novoId) + '/notifications', pular: !novoId, novoId, erro } }];

// Pedido do dono (19/11/2026): SÓ E-MAIL para o cliente em todos os eventos; SMS, WhatsApp, ligação e avisos
// para o dono desligados. Cliente sem e-mail: tudo desligado (o Asaas recusa e-mail sem endereço).
// (Antes, de 09/11 a 19/11/2026, tudo ficava desligado.)
const DESEJADO = [{"event":"PAYMENT_CREATED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_UPDATED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":10,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"SEND_LINHA_DIGITAVEL","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":7,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_RECEIVED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false}];
const n = $('Pede notificacoes').first().json;
const temEmail = !!String((($('Decide').first().json || {}).payload || {}).email || '').trim();
if (!n.novoId) return [{ json: { pular: true } }];
const lista = ($input.first().json || {}).data || [];
const itens = [];
for (const alvo of DESEJADO) {
  const atual = lista.find((x) => x.event === alvo.event && x.scheduleOffset === alvo.offset);
  if (!atual) continue;
  itens.push({ json: { conta: n.conta, metodo: 'PUT', url: 'https://api.asaas.com/v3/notifications/' + encodeURIComponent(atual.id), corpo: {
    enabled: temEmail, emailEnabledForCustomer: temEmail, smsEnabledForCustomer: false,
    whatsappEnabledForCustomer: false, phoneCallEnabledForCustomer: false,
    emailEnabledForProvider: false, smsEnabledForProvider: false,
  } } });
}
return itens.length ? itens : [{ json: { pular: true } }];

